import { defineSlot } from '../Slot';

/**
 * The people table, column by column. A feature that shows something per person contributes
 * `Header` (a <th>, rendered in the table head) and `Cell` (a <td>, rendered in each person's row).
 */
export const PersonHeaders = defineSlot<{ sheetId: string }>('person.headers');
export const PersonCells = defineSlot<{ sheetId: string; personId: number }>('person.cells');
  const [asOf, setAsOf] = useState('');
  const shown = (useQuery(statementsQuery(sheetId)).data ?? []).find((s) => s.personId === personId);
  const take = useMutation({
    mutationFn: (date: string) =>
      postJson<Statements>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`,
        { asOf: date.trim() },
        user,
      ),
    // The claims are re-read first, so the count moves on only once the bound figures show.
    onSuccess: async () => {
      setAsOf('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) });
    },
    // A refused date is not kept for the next statement, which is taken now unless a date is given again.
    onError: () => {
      setAsOf('');
      setError('The statement could not be taken.');
    },
  });
  const cancel = useMutation({
    mutationFn: () =>
      putJson<Statements>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unstate`, {}, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) });
    },
    onError: () => setError('The statement could not be cancelled.'),
  });

  return (
    <td>
      <span data-testid="person-statement-count">{shown?.count ?? 0}</span>{' '}
      <span data-testid="person-stated-total">{shown?.dueTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{shown?.date ?? ''}</span>{' '}
      <input
        data-testid="person-statement-asof"
        type="date"
        title="As of"
        value={asOf}
        onChange={(e) => {
          setError('');
          setAsOf(e.target.value);
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          once(() => take.mutateAsync(asOf));
        }}
      >
        Statement
  );
  const figures = overdueClaims.map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late));
  return { count: overdueClaims.length, total: sumDue(figures) };
}

function ClaimDueBy({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const late = useLate(sheetId);
  return (
    <>
      <td data-testid="claim-due-by">{claim.dueBy}</td>
      <td data-testid="claim-overdue">{isOverdue(claim, late) ? 'yes' : 'no'}</td>
    </>
  );
}

function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const data = useOverdueData(sheetId);
  const person = data.people.find((p) => p.id === personId);
  const { count, total } = person ? overdue(data, person) : { count: 0, total: '0.00' };
  return (
    <td>
      <span data-testid="person-overdue-count">{count}</span> /{' '}
      <span data-testid="person-overdue-total">{total}</span>
    </td>
  );
}

/** The sheet's overdue claims that count: how many, and their total (every person's, trimmed of the highest and lowest). */
export function useSheetOverdue(sheetId: string) {
  const data = useOverdueData(sheetId);
  const { count } = overdue(data);
  return { count, total: trimmedSum(data.people.map((p) => overdue(data, p).total)) };
}

/** One person's overdue-total, as in their row; null when there is no such person. */
export function usePersonOverdueTotal(sheetId: string, personId: number | undefined) {
  const data = useOverdueData(sheetId);
  const person = data.people.find((p) => p.id === personId);
  return person ? overdue(data, person).total : null;
}

